.historyTable{
  overflow-y: auto;
  overflow-x: hidden;
  padding-top: 0px;
  max-height: calc((100vh - 254px) - 24px);
  .historyHang{
    display: grid;
    grid-template-columns: 150px 80px auto;
    .cell{
      padding: 9px;
      border-bottom: 1px solid #e5e5e5;
    }
    .diffHeader{
      display: grid;
      grid-template-columns: 50% 50%;
      grid-gap: 10px;
      word-break: break-all;
    }
  }
}



